    public var appVersion: String

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(projectKey: String, endpoint: String, sessionTimeoutMs: UInt64, sampleRate: Double, excludeElements: [String], excludeScreens: [String], maskElements: [String], storageDirectory: String?, appVersion: String) {
        self.projectKey = projectKey
        self.endpoint = endpoint
        self.sessionTimeoutMs = sessionTimeoutMs
        self.sampleRate = sampleRate
        self.excludeElements = excludeElements
        self.excludeScreens = excludeScreens
        self.maskElements = maskElements
        self.storageDirectory = storageDirectory
        self.appVersion = appVersion
    }
}



extension InitConfig: Equatable, Hashable {
    public static func ==(lhs: InitConfig, rhs: InitConfig) -> Bool {
        if lhs.projectKey != rhs.projectKey {
            return false
        }
        if lhs.endpoint != rhs.endpoint {
            return false
        }
        if lhs.sessionTimeoutMs != rhs.sessionTimeoutMs {
            return false
        }
        if lhs.sampleRate != rhs.sampleRate {
            return false
        }
        if lhs.excludeElements != rhs.excludeElements {
            return false
        }
        if lhs.excludeScreens != rhs.excludeScreens {
            return false
        }
        if lhs.maskElements != rhs.maskElements {
            return false
        }
        if lhs.storageDirectory != rhs.storageDirectory {
            return false
        }
        if lhs.appVersion != rhs.appVersion {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(projectKey)
        hasher.combine(endpoint)
        hasher.combine(sessionTimeoutMs)
        hasher.combine(sampleRate)
        hasher.combine(excludeElements)
        hasher.combine(excludeScreens)
        hasher.combine(maskElements)
        hasher.combine(storageDirectory)
        hasher.combine(appVersion)
    }
}


